action_details.action_postfix:
// Physical nexus established - filing required
// Apportionment will be calculated by tables 7000-7500
"Michigan filing required: Physical presence (office, employees, or property)" job.audit_trail swap addto

// Economic nexus established per Wayfair - filing required
// Apportionment will be calculated by tables 7000-7500
"Michigan filing required: Economic nexus ($100,000 gross receipts threshold)" job.audit_trail swap addto

// Calculate Michigan state additions
0.0 /additions xdef

// Michigan requires addback of federal bond interest
// additions = additions + revenue.federal_bond_interest;

// Michigan may require IRC 199A addback (check current law)
// additions = additions + result.section_199a_deduction;

// Michigan partially decouples from federal bonus depreciation
// additions = additions + result.bonus_depreciation_total;

additions /apportionment.state_additions xdef

// Calculate Michigan state subtractions
0.0 /subtractions xdef

// Michigan municipal bond interest (if taxed federally)
// subtractions = subtractions + revenue.mi_municipal_interest;

// Michigan allows NOL deduction
// subtractions = subtractions + result.state_nol_deduction;

subtractions /apportionment.state_subtractions xdef

"Michigan state additions: $" apportionment.state_additions get cvs strconcat
", subtractions: $" strconcat apportionment.state_subtractions get cvs strconcat
job.audit_trail swap addto

// Michigan uses 6% flat rate apportionment.state_taxable_income get apportionment.state_tax_rate get mul /apportionment.state_tax xdef
// Subtract state credits apportionment.state_tax get apportionment.state_credits get sub 0.0 max /apportionment.state_tax xdef
// Calculate refund or amount owed apportionment.state_payments get apportionment.state_tax get sub /apportionment.state_refund_or_owed xdef
"Michigan tax calculated: State taxable income $" apportionment.state_taxable_income get cvs strconcat " × 6.0% = $" strconcat apportionment.state_tax get cvs strconcat job.audit_trail swap addto
